package com.taskflow.service; import com.taskflow.dto.TaskDtos.*; import com.taskflow.entity.*; import com.taskflow.exception.*; import com.taskflow.repository.*; import java.util.*; import org.springframework.http.*; import org.springframework.stereotype.*;
@Service public class TaskService{final TaskRepository ts;final ProjectRepository ps;final UserRepository us;public TaskService(TaskRepository t,ProjectRepository p,UserRepository u){ts=t;ps=p;us=u;}Project project(String e,Long id){User u=us.findByEmail(e).orElseThrow(()->new ApiException(HttpStatus.UNAUTHORIZED,"User not found"));return ps.findByIdAndOwnerId(id,u.getId()).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Project not found"));}TaskResponse d(Task t){return new TaskResponse(t.getId(),t.getTitle(),t.getDescription(),t.getStatus());}public List<TaskResponse> all(String e,Long pid){project(e,pid);return ts.findAllByProjectIdOrderByIdDesc(pid).stream().map(this::d).toList();}public TaskResponse create(String e,Long pid,TaskRequest r){Task t=new Task();t.setProject(project(e,pid));t.setTitle(r.title());t.setDescription(r.description());t.setStatus(r.status()==null?TaskStatus.TODO:r.status());return d(ts.save(t));}public TaskResponse update(String e,Long pid,Long id,TaskRequest r){project(e,pid);Task t=ts.findByIdAndProjectId(id,pid).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Task not found"));t.setTitle(r.title());t.setDescription(r.description());t.setStatus(r.status()==null?TaskStatus.TODO:r.status());return d(ts.save(t));}public void delete(String e,Long pid,Long id){project(e,pid);Task t=ts.findByIdAndProjectId(id,pid).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Task not found"));ts.delete(t);}}
